// Three potential crash vectors analyzed:
// 1. Go panic from slice OOB: blocked by ValidFields len check (ErrMismatchLength)
// 2. C library memory error from out-of-bounds cell_index: blocked by ValidFields index check (ErrIndexTooLarge)
// 3. nil/empty slice panic: blocked by ErrNoKzgCommitments check
//
// Attack scenario: Index=128 sidecar
// decodePubsubMessage -> succeeds (valid uint64)
// blocks.NewRODataColumn -> wraps struct (no bounds check)
// verifier.ValidFields() -> VerifyDataColumnSidecar -> 128 >= 128 -> ErrIndexTooLarge
// validateDataColumn returns (pubsub.ValidationReject, err) at line 82
// KZG path at line 148 NEVER reached
//
// Note: kzg.go wrapper has NO per-index cell_index range check before C call:
func VerifyCellKZGProofBatch(commitmentsBytes []Bytes48, cellIndices []uint64, cells []Cell, proofsBytes []Bytes48) (bool, error) {
    ckzgCells := make([]ckzg4844.Cell, len(cells))
    for i := range cells { ckzgCells[i] = ckzg4844.Cell(cells[i]) }
    return ckzg4844.VerifyCellKZGProofBatch(commitmentsBytes, cellIndices, ckzgCells, proofsBytes)
    // No per-index bounds check here -- relies on application-layer ValidFields
}
